 ('quart', 'quartile', 'tứ phân vị', 'one of three numbers \\(Q_1,Q_2,Q_3\\) that cut the data into four equal parts.', 'một trong ba số \\(Q_1,Q_2,Q_3\\) chia mẫu số liệu thành bốn phần bằng nhau.', '\\(Q_2\\) is the median.', '\\(Q_1,Q_2,Q_3\\)'),
 ('iqr', 'interquartile range', 'khoảng tứ phân vị', 'the difference \\(\\Delta_Q=Q_3-Q_1\\); it measures the spread of the middle half of the data.', 'hiệu \\(\\Delta_Q=Q_3-Q_1\\); đo độ phân tán của nửa giữa mẫu số liệu.', 'The interquartile range is 15.', '\\(\\Delta_Q\\)'),
 ('disp', 'dispersion (spread)', 'độ phân tán', 'how far the data are spread out from each other.', 'mức độ các giá trị trải rộng, xa nhau.', 'A larger range means a larger spread.', ''),
 ('gdata', 'grouped data', 'mẫu số liệu ghép nhóm', 'data put into groups (classes) with a frequency for each group.', 'số liệu được chia thành các nhóm, mỗi nhóm có một tần số.', 'Heights in groups \\([150;160)\\), \\([160;170)\\).', ''),
 ('cumf', 'cumulative frequency', 'tần số tích lũy', 'the number of data values up to the end of a group.', 'số giá trị của mẫu từ đầu đến hết một nhóm.', 'The cumulative frequency of the second group is 12.', ''),
