goals = [('find the [[range]] of grouped data;', 'tìm [[khoảng biến thiên]] của [[mẫu số liệu ghép nhóm]];'), ('find the quartiles \\(Q_1,Q_2,Q_3\\) with the formula;', 'tìm các [[tứ phân vị]] \\(Q_1,Q_2,Q_3\\) bằng công thức;'), ('compute the interquartile range \\(\\Delta_Q=Q_3-Q_1\\);', 'tính [[khoảng tứ phân vị]] \\(\\Delta_Q=Q_3-Q_1\\);'), ('compare the [[dispersion (spread)]] of two data sets in English.', '[[so sánh]] [[độ phân tán]] của hai mẫu số liệu bằng tiếng Anh.')]
goals[0] = ('find the range of grouped data;', 'tìm [[khoảng biến thiên]] của [[mẫu số liệu ghép nhóm]];'); goals[3] = ('compare the spread of two data sets in English.', '[[so sánh]] [[độ phân tán]] của hai mẫu số liệu bằng tiếng Anh.')
phrases = [('<b>Find the range of the data.</b>', 'Tìm khoảng biến thiên của mẫu số liệu.'), ('<b>Find the first quartile \\(Q_1\\).</b>', 'Tìm tứ phân vị thứ nhất \\(Q_1\\).'), ('<b>Find the interquartile range.</b>', 'Tìm khoảng tứ phân vị.'), ('<b>Which sample is more spread out?</b>', 'Mẫu nào phân tán hơn?'), ('<b>The data are more concentrated.</b>', 'Số liệu tập trung hơn.')]
review = T('From Grade 11: grouped data with groups \\([u_i;u_{i+1})\\) of width \\(h\\), frequencies \\(n_i\\), sample size \\(n\\), cumulative frequency, and the median formula \\(M_e=u_m+\\dfrac{\\frac{n}{2}-C}{n_m}h\\).', 'Từ lớp 11: số liệu ghép nhóm có nhóm \\([u_i;u_{i+1})\\) độ rộng \\(h\\), tần số \\(n_i\\), cỡ mẫu \\(n\\), tần số tích lũy và công thức trung vị \\(M_e=u_m+\\dfrac{\\frac{n}{2}-C}{n_m}h\\).')
t1 = GT(0, 10, [4, 8, 10, 6, 4]); t2 = GT(100, 5, [4, 6, 4, 2])
theory = '<h3>9.1 %s</h3>' % TI('Range', 'Khoảng biến thiên')
theory += BOX('blue', ('Range of grouped data', 'Khoảng biến thiên của mẫu ghép nhóm'), M('R=u_{k+1}-u_1'), T('Right end of the last group minus left end of the first group. It uses only two numbers, so one extreme value changes it a lot.', 'Đầu mút phải của nhóm cuối trừ đầu mút trái của nhóm đầu. Chỉ dùng hai số nên một giá trị cực đoan làm \\(R\\) thay đổi nhiều.'))
