theory += '<h3>9.3 %s</h3>' % TI('Interquartile range', 'Khoảng tứ phân vị')
theory += BOX('blue', ('Definition', 'Định nghĩa'), M('\\Delta_Q=Q_3-Q_1'), T('\\(\\Delta_Q\\) shows how wide the middle half of the data is. A smaller \\(\\Delta_Q\\) means more concentrated data. It is not changed much by extreme values.', '\\(\\Delta_Q\\) cho biết nửa giữa của số liệu trải rộng bao nhiêu. \\(\\Delta_Q\\) nhỏ hơn nghĩa là số liệu tập trung hơn. Giá trị cực đoan ít ảnh hưởng đến \\(\\Delta_Q\\).'))
theory += BOX('yellow', ('Watch out!', 'Lưu ý'), T('Compare spreads only for data with the same unit. The sample with the smaller \\(\\Delta_Q\\) is more concentrated, even if its range is larger.', 'Chỉ so sánh độ phân tán khi cùng đơn vị. Mẫu có \\(\\Delta_Q\\) nhỏ hơn thì tập trung hơn, kể cả khi khoảng biến thiên của nó lớn hơn.'))
