examples = EXAMPLE(1, ('Basic', 'Cơ bản'), ('The range', 'Khoảng biến thiên'), T('Heights of plants (cm): %s. Find the range.' % t1.html(), 'Chiều cao cây (cm): %s. Tìm khoảng biến thiên.' % t1.html()), T('Use the ends of the first and last groups.', 'Dùng đầu mút của nhóm đầu và nhóm cuối.'), [T('\\(R=u_{6}-u_1=%d-%d\\).' % (t1.edge(5), t1.edge(0)), '\\(R=u_{6}-u_1=%d-%d\\).' % (t1.edge(5), t1.edge(0)))], T('\\(R=%d\\ \\text{cm}\\).' % t1.rng(), '\\(R=%d\\ \\text{cm}\\).' % t1.rng()))
