examples += EXAMPLE(2, ('Basic', 'Cơ bản'), ('Which group?', 'Nhóm nào?'), T('For the same data (\\(n=%d\\)), which group contains \\(Q_1\\) and which contains \\(Q_3\\)?' % t1.n, 'Với cùng mẫu số liệu (\\(n=%d\\)), nhóm nào chứa \\(Q_1\\), nhóm nào chứa \\(Q_3\\)?' % t1.n), T('Compare \\(\\frac n4\\) and \\(\\frac{3n}4\\) with the cumulative frequencies \\(4,12,22,28,32\\).', 'So sánh \\(\\frac n4\\) và \\(\\frac{3n}4\\) với tần số tích lũy \\(4,12,22,28,32\\).'), [T('\\(\\frac n4=8\\): the first cumulative frequency \\(\\ge8\\) is 12, group \\([10;20)\\).', '\\(\\frac n4=8\\): tần số tích lũy đầu tiên \\(\\ge8\\) là 12, nhóm \\([10;20)\\).'), T('\\(\\frac{3n}4=24\\): the first cumulative frequency \\(\\ge24\\) is 28, group \\([30;40)\\).', '\\(\\frac{3n}4=24\\): tần số tích lũy đầu tiên \\(\\ge24\\) là 28, nhóm \\([30;40)\\).')], T('\\(Q_1\\in[10;20)\\), \\(Q_3\\in[30;40)\\).', '\\(Q_1\\in[10;20)\\), \\(Q_3\\in[30;40)\\).'))
assert t1.n == 32 and [t1.cum(i + 1) for i in range(5)] == [4, 12, 22, 28, 32] and t1.quant(1, 4)[0] == 1 and t1.quant(3, 4)[0] == 3
examples += EXAMPLE(3, ('Intermediate', 'Trung bình'), ('Compute \\(Q_1\\), \\(Q_3\\)', 'Tính \\(Q_1\\), \\(Q_3\\)'), T('Compute \\(Q_1\\), \\(Q_3\\) and \\(\\Delta_Q\\) for the same data.', 'Tính \\(Q_1\\), \\(Q_3\\) và \\(\\Delta_Q\\) cho mẫu số liệu trên.'), T('Use \\(Q_j=u_m+\\dfrac{\\frac{jn}{4}-C}{n_m}h\\).', 'Dùng \\(Q_j=u_m+\\dfrac{\\frac{jn}{4}-C}{n_m}h\\).'), [T('\\(Q_1=10+\\dfrac{8-4}{8}\\cdot10=15\\).', '\\(Q_1=10+\\dfrac{8-4}{8}\\cdot10=15\\).'), T('\\(Q_3=30+\\dfrac{24-22}{6}\\cdot10=\\dfrac{100}3\\).', '\\(Q_3=30+\\dfrac{24-22}{6}\\cdot10=\\dfrac{100}3\\).'), T('\\(\\Delta_Q=\\dfrac{100}3-15=\\dfrac{55}3\\approx18.3\\).', '\\(\\Delta_Q=\\dfrac{100}3-15=\\dfrac{55}3\\approx18{,}3\\).')], T('\\(Q_1=15\\), \\(Q_3=\\dfrac{100}3\\approx33.3\\), \\(\\Delta_Q\\approx18.3\\).', '\\(Q_1=15\\), \\(Q_3=\\dfrac{100}3\\approx33{,}3\\), \\(\\Delta_Q\\approx18{,}3\\).'))
