examples += EXAMPLE(5, ('Advanced', 'Nâng cao'), ('Range or \\(\\Delta_Q\\)?', 'Khoảng biến thiên hay \\(\\Delta_Q\\)?'), T('Sample X has \\(R=40\\), \\(\\Delta_Q=10\\). Sample Y has \\(R=30\\), \\(\\Delta_Q=16\\). Which sample is more spread out in the middle half? Which has the larger range?', 'Mẫu X có \\(R=40\\), \\(\\Delta_Q=10\\). Mẫu Y có \\(R=30\\), \\(\\Delta_Q=16\\). Mẫu nào phân tán hơn ở nửa giữa? Mẫu nào có khoảng biến thiên lớn hơn?'),
  T('\\(R\\) looks at the two extremes; \\(\\Delta_Q\\) looks at the middle half.', '\\(R\\) nhìn hai giá trị đầu mút; \\(\\Delta_Q\\) nhìn nửa giữa số liệu.'), [T('Middle half: \\(16\\gt10\\), so Y is more spread out.', 'Nửa giữa: \\(16\\gt10\\) nên Y phân tán hơn.'), T('Range: \\(40\\gt30\\), so X has the larger range.', 'Khoảng biến thiên: \\(40\\gt30\\) nên X có \\(R\\) lớn hơn.')], T('Y is more spread out in the middle; X has the larger range. \\(\\Delta_Q\\) is more reliable when there are extreme values.', 'Y phân tán hơn ở nửa giữa; X có \\(R\\) lớn hơn. \\(\\Delta_Q\\) đáng tin hơn khi có giá trị cực đoan.'))

def W(ok, cands):
    out = []
    for c in cands + [dec(float(str(ok).replace('-', '')) + k) if False else dec(F(ok) + F(k, 2)) for k in (5, -5, 7, -7, 9, 11, 13)]:
        if c != ok and c not in out: out.append(c)
    return out[:4]
import gq, gq_build
from gq import *
